// 16 x 8 registers, combinational read: every word is visible at once.
// Synthesis builds flip-flops + a 16:1 multiplexer (FPGA: LUT RAM).
module regs16 (
  input  logic       clk, we,
  input  logic [3:0] wa, ra,
  input  logic [7:0] wd,
  output logic [7:0] rd
);
  logic [7:0] regs [16];
  always_ff @(posedge clk) if (we) regs[wa] <= wd;
  assign rd = regs[ra];                 // asynchronous read
endmodule

// 1024 x 32 memory, synchronous read: the read data is registered.
// This pattern can be mapped to an SRAM macro (ASIC) or block RAM (FPGA).
module ram1k (
  input  logic        clk, we,
  input  logic [9:0]  addr,
  input  logic [31:0] din,
  output logic [31:0] dout
);
  logic [31:0] mem [1024];
  always_ff @(posedge clk) begin
    if (we) mem[addr] <= din;
    dout <= mem[addr];                  // synchronous read
  end
endmodule
